WITH valid AS (SELECT id, session_id, event_type, page, event_time, duration_sec, HOUR(event_time) AS event_time_hour, COALESCE(page, 'NONE') AS resolved_page FROM web_events WHERE page IS NOT NULL AND session_id = 24) SELECT id, session_id, event_type, page, event_time, duration_sec, event_time_hour, resolved_page, LAST_VALUE(event_time_hour, TRUE) OVER (ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_event_time_hour, NTILE(5) OVER (PARTITION BY session_id ORDER BY event_time_hour, id) AS event_time_hour_bucket FROM valid;
